            else if (id == 3) MoveSelectedGlobalDbDeclaration(1);
            else if (id == 4) globalDbRemoveMember.EmitSignal(BaseButton.SignalName.Pressed);
        };
        globalDbPropertiesMember.Pressed += ShowSelectedGlobalDbDeclarationProperties;
