        void ActivateTiaProgramBlock(int blockIndex)
        {
            var block = document.Blocks[blockIndex];
            var blockCode = block.BlockType switch
            {
                LadderBlockType.OrganizationBlock => "OB",
                LadderBlockType.FunctionBlock => "FB",
                LadderBlockType.DataBlock => "DB",
                _ => "FC",
            };
            var key = BlockDocumentKey(block.Id);
            AddEditorDocumentTab(key, $"{block.Name} [{blockCode}]");
            ActivateEditorDocument(key);
            blockItems[blockIndex].Select(0);
            organization.ScrollToItem(blockItems[blockIndex]);
            if (block.BlockType == LadderBlockType.DataBlock)
                output.Text = $"[color=#18864b]{Escape(block.Name)} global DB opened.[/color] Edit its declarations in the Project inspector.";
            else
            {
                output.Text = $"[color=#18864b]{Escape(block.Name)} opened in the program editor.[/color]";
                canvas.GrabFocus();
            }
        }
        if (siemens)
            _tiaProgramBlockActivator = blockIndex => ResolvePendingEditorForms(() => ActivateTiaProgramBlock(blockIndex));
        organization.ItemActivated += () =>
        {
            if (restoringOrganizationSelection) return;
            var kind = organization.GetSelected()?.GetMetadata(0).AsString() ?? string.Empty;
            if (siemens && kind.StartsWith("instance-db:", StringComparison.Ordinal)
                && int.TryParse(kind.AsSpan("instance-db:".Length), out var instanceDbNumber))
            {
                ResolvePendingEditorForms(() => OpenInstanceDbDocument(instanceDbNumber));
                return;
            }
            if (siemens && kind.StartsWith("program:", StringComparison.Ordinal)
                && int.TryParse(kind.AsSpan("program:".Length), out var blockIndex)
                && blockIndex >= 0 && blockIndex < document.Blocks.Count)
            {
                _tiaProgramBlockActivator!(blockIndex);
                return;
            }
            if (siemens && kind.StartsWith("tag-table:", StringComparison.Ordinal))
            {
                var tableName = kind["tag-table:".Length..];
                ResolvePendingEditorForms(() => OpenTagDocument(tableName.Length == 0 ? null : tableName));
                return;
            }
            if (siemens && EditorDocumentIdentity.TryResolveWatchTableIndex(document, kind, out _))
            {
                ResolvePendingEditorForms(() =>
                {
                    if (!EditorDocumentIdentity.TryResolveWatchTableIndex(document, kind, out var resolvedWatchIndex))
                    {
                        output.Text = "The selected watch table is no longer available.";
                        return;
                    }
                    OpenWatchTableDocument(document.WatchTables[resolvedWatchIndex]);
                });
                return;
            }
            if (siemens && kind is "controller" or "device" or "diagnostics")
            {
                projectTreeContextMetadata = kind;
                projectTreeContextLabel = organization.GetSelected()?.GetText(0) ?? kind;
                projectTreeContextMenu.EmitSignal(PopupMenu.SignalName.IdPressed, 0L);
                return;
            }
            if (kind is not ("add-block" or "add-tag-table" or "add-watch-table")) return;
            ResolvePendingEditorForms(() =>
            {
                if (kind == "add-block") addBlock.EmitSignal(BaseButton.SignalName.Pressed);
                else if (kind == "add-tag-table") OpenTagTableCreation();
                else openWatchTableCreation();
            });
        };
        openInstanceDbOwnerAction = dbNumber =>
        {
            if (FindInstanceDbOwnerLocator(dbNumber) is not { } ownerLocator
                || ResolveInstanceDbOwner(ownerLocator) is not { } owner)
            {
                output.Text = "[color=#d64545]The generated DB owner is no longer present.[/color]";
                return;
            }

            var ownerBlockIndex = -1;
            var ownerRungIndex = -1;
            if (owner.Instance is not null)
            {
                for (var blockIndex = 0; blockIndex < document.Blocks.Count && ownerRungIndex < 0; blockIndex++)
                {
                    var rungIndex = document.Blocks[blockIndex].Rungs.FindIndex(rung =>
                        rung.IsCall && rung.CallInstanceId == owner.Instance.Id);
                    if (rungIndex < 0) continue;
                    ownerBlockIndex = blockIndex;
                    ownerRungIndex = rungIndex;
                }
            }
            else if (owner.InstructionBlock is not null)
            {
                ownerBlockIndex = document.Blocks.FindIndex(block => block.Id == owner.InstructionBlock.Id);
                ownerRungIndex = owner.RungIndex;
            }

            if (ownerBlockIndex >= 0 && ownerRungIndex >= 0)
            {
                SwitchEditorBlock(ownerBlockIndex, restoreView: true);
                canvas.SelectElement(ownerRungIndex, -1, -1, output: true, notify: false);
                OpenInstructionProperties();
                output.Text = $"[b]Instance DB owner[/b] · {Escape(document.Blocks[ownerBlockIndex].Name)} · Network {ownerRungIndex + 1}";
            }
            else if (owner.InstanceBlock is not null)
            {
                var instanceBlockIndex = document.Blocks.FindIndex(block => block.Id == owner.InstanceBlock.Id);
                if (instanceBlockIndex >= 0)
                {
                    ActivateTiaProgramBlock(instanceBlockIndex);
                    output.Text = $"[b]Instance DB owner block[/b] · {Escape(owner.InstanceBlock.Name)}";
                    return;
                }
                output.Text = "[color=#d64545]The generated DB owner could not be opened.[/color]";
            }
            else
            {
                output.Text = "[color=#d64545]The generated DB owner could not be opened.[/color]";
            }
        };
        if (siemens)
        {
            void SetProjectTreeContextActionEnabled(int id, bool enabled)
            {
                var index = projectTreeContextMenu.GetItemIndex(id);
                if (index >= 0) projectTreeContextMenu.SetItemDisabled(index, !enabled);
            }

            bool ConfigureProjectTreeObjectContext(string metadata)
            {
                var blockIndex = -1;
                var isProgramBlock = metadata.StartsWith("program:", StringComparison.Ordinal)
                    && int.TryParse(metadata.AsSpan("program:".Length), out blockIndex)
                    && blockIndex >= 0 && blockIndex < document.Blocks.Count;
                var isTagTable = metadata.StartsWith("tag-table:", StringComparison.Ordinal)
                    && metadata.Length > "tag-table:".Length;
                var isWatchTable = EditorDocumentIdentity.TryResolveWatchTableIndex(document, metadata, out _);
                var isInstanceDb = metadata.StartsWith("instance-db:", StringComparison.Ordinal)
                    && int.TryParse(metadata.AsSpan("instance-db:".Length), out _);
                var isControllerObject = metadata is "controller" or "device" or "diagnostics";
                var isFolder = metadata is "blocks" or "tags" or "watch";
                if (!isProgramBlock && !isTagTable && !isWatchTable && !isInstanceDb && !isControllerObject && !isFolder)
                    return false;

                SetProjectTreeContextActionEnabled(0, true);
                SetProjectTreeContextActionEnabled(1, true);
                SetProjectTreeContextActionEnabled(6, isProgramBlock);
                if (isProgramBlock)
                {
                    var canDelete = document.CanRemoveBlock(document.Blocks[blockIndex].Id, out _);
                    SetProjectTreeContextActionEnabled(2, !ChallengeMutationLocked);
                    SetProjectTreeContextActionEnabled(3, !ChallengeMutationLocked);
                    SetProjectTreeContextActionEnabled(4, !ChallengeMutationLocked && canDelete);
                }
                else if (isTagTable)
                {
                    var tableName = metadata["tag-table:".Length..];
                    var isSceneIo = tableName.Equals(SceneLadderProject.SceneIoTagTableName, StringComparison.OrdinalIgnoreCase);
                    var isUserTable = !tableName.Equals("Default tag table", StringComparison.OrdinalIgnoreCase)
                        && !isSceneIo
                        && document.TagTables.Contains(tableName, StringComparer.OrdinalIgnoreCase);
                    var isEmpty = !document.Tags.Any(tag => tag.TagTable.Equals(tableName, StringComparison.OrdinalIgnoreCase))
                        && !document.UserConstants.Any(constant => constant.TagTable.Equals(tableName, StringComparison.OrdinalIgnoreCase));
                    SetProjectTreeContextActionEnabled(2, !ChallengeMutationLocked && isUserTable);
                    SetProjectTreeContextActionEnabled(3, !ChallengeMutationLocked && !isSceneIo);
                    SetProjectTreeContextActionEnabled(4, !ChallengeMutationLocked && isUserTable && isEmpty);
                }
                else if (isWatchTable)
                {
                    SetProjectTreeContextActionEnabled(2, !ChallengeMutationLocked);
                    SetProjectTreeContextActionEnabled(3, !ChallengeMutationLocked);
                    SetProjectTreeContextActionEnabled(4, !ChallengeMutationLocked && document.WatchTables.Count > 1);
                }
                else
                {
                    SetProjectTreeContextActionEnabled(2, false);
                    SetProjectTreeContextActionEnabled(3, false);
                    SetProjectTreeContextActionEnabled(4, false);
                }
                return true;
            }

            string SelectedProjectTreePath()
            {
                var item = organization.GetSelected();
                if (item is null) return string.Empty;
                var selectedMetadata = item.GetMetadata(0).AsString();
                if (projectTreeContextMetadata is "blocks" or "tags" or "watch"
                    && selectedMetadata is "add-block" or "add-tag-table" or "add-watch-table" or "tag-table:")
                    item = item.GetParent();

                var segments = new Stack<string>();
                for (var current = item; current is not null; current = current.GetParent())
                {
                    var text = current.GetText(0).Trim();
                    if (!string.IsNullOrEmpty(text)) segments.Push(text);
                }
                return string.Join(" / ", segments);
            }

            void ShowProjectObjectProperties(string title, params string[] details)
            {
                projectObjectPropertiesDialog.Title = $"{title} properties";
                projectTreeContextPath = SelectedProjectTreePath();
                projectObjectPropertiesDialog.DialogText = string.Join("\n",
                    string.IsNullOrWhiteSpace(projectTreeContextPath)
                        ? details
                        : new[] { $"Location: {projectTreeContextPath}" }.Concat(details));
                propertiesCopyPath.Disabled = string.IsNullOrWhiteSpace(projectTreeContextPath);
                var openIndex = projectTreeContextMenu.GetItemIndex(0);
                propertiesOpen.Disabled = openIndex < 0 || projectTreeContextMenu.IsItemDisabled(openIndex);
                propertiesOpen.Visible = !propertiesOpen.Disabled;
                propertiesOpenOwner.Visible = projectTreeContextMetadata.StartsWith("instance-db:", StringComparison.Ordinal);
                projectObjectPropertiesDialog.PopupCentered(new Vector2I(720, 300));
            }

            organization.GuiInput += input =>
            {
                if (input is InputEventKey { Pressed: true, Echo: false } key
                    && key.Keycode is Key.F2 or Key.Delete)
                {
                    var keyboardMetadata = organization.GetSelected()?.GetMetadata(0).AsString() ?? string.Empty;
                    var rename = key.Keycode == Key.F2;
                    var permitted = false;
                    if (!ChallengeMutationLocked
                        && keyboardMetadata.StartsWith("program:", StringComparison.Ordinal)
                        && int.TryParse(keyboardMetadata.AsSpan("program:".Length), out var selectedBlockIndex)
                        && selectedBlockIndex >= 0 && selectedBlockIndex < document.Blocks.Count)
                    {
                        permitted = rename || document.CanRemoveBlock(document.Blocks[selectedBlockIndex].Id, out _);
                    }
                    else if (!ChallengeMutationLocked
                             && keyboardMetadata.StartsWith("tag-table:", StringComparison.Ordinal)
                             && keyboardMetadata.Length > "tag-table:".Length)
                    {
                        var tableName = keyboardMetadata["tag-table:".Length..];
                        var isUserTable = !tableName.Equals("Default tag table", StringComparison.OrdinalIgnoreCase)
                            && !tableName.Equals(SceneLadderProject.SceneIoTagTableName, StringComparison.OrdinalIgnoreCase)
                            && document.TagTables.Contains(tableName, StringComparer.OrdinalIgnoreCase);
                        permitted = isUserTable && (rename
                            || !document.Tags.Any(tag => tag.TagTable.Equals(tableName, StringComparison.OrdinalIgnoreCase))
                            && !document.UserConstants.Any(constant => constant.TagTable.Equals(tableName, StringComparison.OrdinalIgnoreCase)));
                    }
                    else if (!ChallengeMutationLocked
                             && EditorDocumentIdentity.TryResolveWatchTableIndex(document, keyboardMetadata, out _))
                    {
                        permitted = rename || document.WatchTables.Count > 1;
                    }

                    if (permitted)
                    {
                        projectTreeContextMetadata = keyboardMetadata;
                        projectTreeContextMenu.EmitSignal(PopupMenu.SignalName.IdPressed, rename ? 2L : 4L);
                    }
                    else
                    {
                        output.Text = ChallengeMutationLocked
                            ? "Project changes are locked for this lesson."
                            : $"{(rename ? "Rename" : "Delete")} is not available for the selected project-tree object.";
                    }
                    organization.AcceptEvent();
                    return;
                }

                if (input is not InputEventMouseButton
                    {
                        Pressed: true,
                        ButtonIndex: MouseButton.Right,
                    } mouse) return;

                var row = organization.GetItemAtPosition(mouse.Position);
                if (row is null) return;
                var metadata = row.GetMetadata(0).AsString();
                var isCreationTarget = metadata is "blocks" or "tags" or "watch" or "add-block" or "add-tag-table" or "add-watch-table";
                if (!isCreationTarget && !ConfigureProjectTreeObjectContext(metadata)) return;

                row.Select(0);
                projectTreeContextMetadata = metadata;
                projectTreeContextLabel = row.GetText(0);
                if (isCreationTarget)
                {
                    var label = metadata is "blocks" or "add-block"
                        ? "Add new block…"
                        : metadata is "tags" or "add-tag-table"
                            ? "Add new tag table…"
                            : "Add new watch table…";
                    projectTreeCreationMenu.SetItemText(projectTreeCreationMenu.GetItemIndex(5), label);
                    projectTreeCreationMenu.SetItemDisabled(projectTreeCreationMenu.GetItemIndex(5), ChallengeMutationLocked);
                    projectTreeCreationMenu.Position = DisplayServer.MouseGetPosition();
                    projectTreeCreationMenu.Popup();
                    organization.AcceptEvent();
                    return;
                }

                projectTreeContextMenu.Position = DisplayServer.MouseGetPosition();
                projectTreeContextMenu.Popup();
                organization.AcceptEvent();
            };

            bool PrepareSelectedProjectObjectContext(out string metadata)
            {
                var row = organization.GetSelected();
                if (row is null)
                {
                    output.Text = "Select a project-tree object before using OPEN or PROPS.";
                    metadata = string.Empty;
                    return false;
                }

                metadata = row.GetMetadata(0).AsString();
                metadata = metadata switch
                {
                    "add-block" => "blocks",
                    "add-tag-table" => "tags",
                    "add-watch-table" => "watch",
                    "tag-table:" => "tags",
                    _ => metadata,
                };
                if (!ConfigureProjectTreeObjectContext(metadata))
                {
                    output.Text = "OPEN and PROPS are not available for the selected project-tree object.";
                    return false;
                }

                projectTreeContextMetadata = metadata;
                projectTreeContextLabel = metadata switch
                {
                    "blocks" => blockFolder.GetText(0),
                    "tags" => tagItem.GetText(0),
                    "watch" => watchFolder.GetText(0),
                    _ => row.GetText(0),
                };
                return true;
            }

            openSelectedProjectObject = () =>
            {
                if (PrepareSelectedProjectObjectContext(out _))
                    projectTreeContextMenu.EmitSignal(PopupMenu.SignalName.IdPressed, 0L);
            };
            showSelectedProjectObjectProperties = () =>
            {
                if (!PrepareSelectedProjectObjectContext(out _)) return;
                projectTreeContextMenu.EmitSignal(PopupMenu.SignalName.IdPressed, 1L);
            };
            showActiveEditorDocumentProperties = () =>
            {
                var target = ActiveEditorDocumentTreeItem();
                if (target is null)
                {
                    output.Text = "The active editor document is no longer present in the Project tree.";
                    return;
                }
                target.Select(0);
                if (!PrepareSelectedProjectObjectContext(out _)) return;
                projectTreeContextMenu.EmitSignal(PopupMenu.SignalName.IdPressed, 1L);
            };

            projectTreeContextMenu.IdPressed += id => ResolvePendingEditorForms(() =>
            {
                var metadata = projectTreeContextMetadata;
                if (metadata is "blocks" or "tags" or "watch")
                {
                    if (id == 0)
                    {
                        if (metadata == "blocks")
                        {
                            ShowProjectDock();
                            projectTabs.CurrentTab = 0;
                            blockFolder.SetCollapsed(false);
                            blockFolder.Select(0);
                            organization.ScrollToItem(blockFolder);
                            output.Text = $"[b]Program blocks[/b] · {document.Blocks.Count} authored block(s).";
                        }
                        else if (metadata == "tags")
                        {
                            OpenTagDocument(null);
                            output.Text = $"[b]PLC tags[/b] · {document.Tags.Count} tag(s) in {document.TagTables.Count} table(s).";
                        }
                        else
                        {
                            OpenWatchTableDocument(document.ActiveWatchTable);
                            output.Text = $"[b]Watch tables[/b] · {document.WatchTables.Count} table(s); {Escape(document.ActiveWatchTable.Name)} is active.";
                        }
                    }
                    else if (id == 1)
                    {
                        if (metadata == "blocks")
                        {
                            ShowProjectObjectProperties(projectTreeContextLabel,
                                "Object type: Program blocks folder",
                                $"Organization blocks (OB): {document.Blocks.Count(block => block.BlockType == LadderBlockType.OrganizationBlock)}",
                                $"Function blocks (FB): {document.Blocks.Count(block => block.BlockType == LadderBlockType.FunctionBlock)}",
                                $"Functions (FC): {document.Blocks.Count(block => block.BlockType == LadderBlockType.Function)}",
                                $"Global data blocks (DB): {document.Blocks.Count(block => block.BlockType == LadderBlockType.DataBlock)}",
                                $"Total authored networks: {document.Blocks.Sum(block => block.Rungs.Count)}",
                                "Add: Available from the project-tree folder menu");
                        }
                        else if (metadata == "tags")
                        {
                            ShowProjectObjectProperties(projectTreeContextLabel,
                                "Object type: PLC tags folder",
                                $"Tag tables: {document.TagTables.Count}",
                                $"PLC tags: {document.Tags.Count}",
                                $"User constants: {document.UserConstants.Count}",
                                $"Scene-bound tags: {document.Tags.Count(tag => !string.IsNullOrWhiteSpace(tag.Binding))}",
                                "Add: Available from the project-tree folder menu");
                        }
                        else
                        {
                            ShowProjectObjectProperties(projectTreeContextLabel,
                                "Object type: Watch tables folder",
                                $"Watch tables: {document.WatchTables.Count}",
                                $"Configured rows: {document.WatchTables.Sum(table => table.Rows.Count)}",
                                $"Active table: {document.ActiveWatchTable.Name}",
                                "Add: Available from the project-tree folder menu",
                                "Minimum: Project must retain at least one watch table");
                        }
                    }
                    return;
                }
                if (metadata == "controller")
                {
                    if (id == 0)
                    {
                        ShowProjectDock();
                        projectTabs.CurrentTab = 0;
                        output.Text = $"[b]{Escape(projectTreeContextLabel)}[/b] · offline controller project · {document.Blocks.Count} block(s), {document.Tags.Count} tag(s).";
                    }
                    else if (id == 1)
                    {
                        ShowProjectObjectProperties(projectTreeContextLabel,
                            "Object type: Offline controller / PLC station",
                            $"Project identity: {document.Id}",
                            $"Program blocks: {document.Blocks.Count}",
                            $"PLC tags: {document.Tags.Count}",
                            $"Tag tables: {document.TagTables.Count}",
                            $"Watch tables: {document.WatchTables.Count}",
                            $"Configured scan period: {document.ScanPeriod.TotalMilliseconds:0.###} ms",
                            $"Runtime scope: {(_externalMode ? "External PLC mode selected" : "Built-in offline simulator")}");
                    }
                    return;
                }
                if (metadata == "device")
                {
                    var boundTags = document.Tags.Count(tag => !string.IsNullOrWhiteSpace(tag.Binding));
                    if (id == 0)
                    {
                        OpenTagDocument(null);
                        output.Text = $"[b]Symbolic I/O[/b] · {boundTags} of {document.Tags.Count} PLC tag(s) have scene bindings.";
                    }
                    else if (id == 1)
                    {
                        ShowProjectObjectProperties(projectTreeContextLabel,
                            "Object type: Symbolic simulator I/O mapping",
                            $"Bound tags: {boundTags}",
                            $"Input-role tags: {document.Tags.Count(tag => tag.Role == PlcVariableRole.Input)}",
                            $"Output-role tags: {document.Tags.Count(tag => tag.Role == PlcVariableRole.Output)}",
                            "Hardware rack / slot: Not modeled",
                            "Physical PLC transport: Not configured by this object");
                    }
                    return;
                }
                if (metadata == "diagnostics")
                {
                    if (id == 0)
                    {
                        ShowBottomDock();
                        bottomPanel.Visible = true;
                        reopenBottomDock.Visible = false;
                        bottomTabs.CurrentTab = 1;
                        output.Text = OfflineDiagnosticStatus();
                    }
                    else if (id == 1)
                    {
                        ShowProjectObjectProperties(projectTreeContextLabel,
                            "Object type: Offline diagnostics entry",
                            $"Controller state: {_virtualSnapshot?.State.ToString().ToUpperInvariant() ?? "NOT LOADED"}",
                            $"Loaded program matches draft: {(_ladderMonitorMatchesLoadedProgram ? "YES" : "NO")}",
                            $"Simulator forces: {_virtualSnapshot?.Forces.Count ?? 0}",
                            $"Last scan: {_virtualSnapshot?.ScanNumber ?? 0}",
                            "Scope: Local simulator diagnostics; not installed-TIA or live-PLC evidence");
                    }
                    return;
                }
                if (metadata.StartsWith("program:", StringComparison.Ordinal)
                    && int.TryParse(metadata.AsSpan("program:".Length), out var blockIndex)
                    && blockIndex >= 0 && blockIndex < document.Blocks.Count)
                {
                    var block = document.Blocks[blockIndex];
                    if (id == 0)
                    {
                        ActivateTiaProgramBlock(blockIndex);
                        return;
                    }
                    if (id == 1)
                    {
                        var typeName = block.BlockType switch
                        {
                            LadderBlockType.OrganizationBlock => "Organization block (OB)",
                            LadderBlockType.FunctionBlock => "Function block (FB)",
                            LadderBlockType.Function => "Function (FC)",
                            LadderBlockType.DataBlock => "Global data block (DB)",
                            _ => block.BlockType.ToString(),
                        };
                        var callSites = document.Blocks
                            .SelectMany(owner => owner.Rungs.Select((rung, networkIndex) => (Owner: owner, Rung: rung, NetworkIndex: networkIndex)))
                            .Where(site => site.Rung.IsCall && site.Rung.CallTarget == block.Id)
                            .ToArray();
                        var callerSummary = callSites.Length == 0
                            ? "None"
                            : string.Join("; ", callSites.Select(site => $"{site.Owner.Name} · Network {site.NetworkIndex + 1}"));
                        var blockInstances = document.Instances.Where(instance => instance.BlockId == block.Id).ToArray();
                        var instanceSummary = blockInstances.Length == 0
                            ? "None"
                            : string.Join("; ", blockInstances.Select(instance => instance.InstanceDataBlock is null
                                ? instance.Name
                                : $"{instance.Name} · DB{instance.InstanceDataBlock.Number} {instance.InstanceDataBlock.Name}"));
                        var schedules = document.Tasks
                            .Select((task, index) => (Task: task, Index: index))
                            .Where(item => item.Task.EntryBlock == block.Id)
                            .ToArray();
                        var scheduleSummary = schedules.Length == 0
                            ? "None"
                            : string.Join("; ", schedules.Select(item =>
                                $"{(siemens ? item.Task.Kind == LadderTaskKind.Continuous ? "OB1" : $"OB{30 + item.Index}" : item.Task.Name)} · {item.Task.Kind} · P{item.Task.Priority}"));
                        var canDelete = document.CanRemoveBlock(block.Id, out var deleteReason);
                        ShowProjectObjectProperties(block.Name,
                            $"Type: {typeName}",
                            $"Contents: {block.Rungs.Count} network(s) · {block.Interface.Count} declaration(s) · {block.SemanticMode} semantics",
                            $"Execution: {scheduleSummary}",
                            $"CALL references: {callerSummary}",
                            $"Assigned instances: {instanceSummary}",
                            $"Offline status: {(_ladderMonitorMatchesLoadedProgram ? "draft matches the loaded local runtime" : "draft differs from the loaded local runtime · Verify + Load required")}",
                            $"Delete: {(canDelete ? "available" : $"protected · {deleteReason}")}",
                            "Boundary: offline RungProof project · no Siemens connection");
                        return;
                    }
                    if (id == 6)
                    {
                        searchQuery.Text = block.Name;
                        ShowToolDock(1);
                        RunProjectSearch(true);
                        output.Text = $"[b]Block cross-reference[/b] · {Escape(block.Name)}";
                        return;
                    }

                    SwitchEditorBlock(blockIndex, restoreView: true);
                    blockItems[blockIndex].Select(0);
                    organization.ScrollToItem(blockItems[blockIndex]);
                    if (id == 2)
                    {
                        ShowProjectDock();
                        projectTabs.CurrentTab = 2;
                        blockName.GrabFocus();
                        blockName.SelectAll();
                        output.Text = $"[b]Rename block[/b] · edit {Escape(block.Name)} and choose RENAME BLOCK.";
                    }
                    else if (id == 3) duplicateBlock.EmitSignal(BaseButton.SignalName.Pressed);
                    else if (id == 4) removeBlock.EmitSignal(BaseButton.SignalName.Pressed);
                    return;
                }

                if (EditorDocumentIdentity.TryResolveWatchTableIndex(document, metadata, out var watchIndex))
                {
                    document.SelectWatchTable(watchIndex);
                    var watch = document.WatchTables[watchIndex];
                    if (id == 1)
                    {
                        var symbolicRowCount = watch.Rows.Count(row => row.ReferenceKind == WatchReferenceKind.Symbolic);
                        var addressRowCount = watch.Rows.Count(row => row.ReferenceKind == WatchReferenceKind.AbsoluteAddress);
                        var deleteStatus = ChallengeMutationLocked
                            ? "Unavailable · project editing is locked during the active challenge"
                            : document.WatchTables.Count > 1
                                ? "Available"
                                : "Protected · project must retain at least one watch table";
                        ShowProjectObjectProperties(watch.Name,
                            "Object type: Watch table",
                            $"Name: {watch.Name}",
                            $"Stable ID: {watch.Id}",
                            $"Configured rows: {watch.Rows.Count}",
                            $"Symbolic references: {symbolicRowCount}",
                            $"Absolute-address references: {addressRowCount}",
                            $"Delete: {deleteStatus}",
                            "Source: Offline RungProof project",
                            $"Editable: {(ChallengeMutationLocked ? "No · active challenge lock" : "Yes · use Rename, Duplicate, or Delete from the project tree")}");
                        return;
                    }
                    OpenWatchTableDocument(watch);
                    if (id == 0) return;
                    if (id == 2) renameWatchTable.EmitSignal(BaseButton.SignalName.Pressed);
                    else if (id == 3) duplicateWatchTable.EmitSignal(BaseButton.SignalName.Pressed);
                    else if (id == 4) removeWatchTable.EmitSignal(BaseButton.SignalName.Pressed);
                    return;
                }

                if (metadata.StartsWith("instance-db:", StringComparison.Ordinal)
                    && int.TryParse(metadata.AsSpan("instance-db:".Length), out var instanceDbNumber))
                {
                    if (id == 1)
                    {
                        var ownerLocator = FindInstanceDbOwnerLocator(instanceDbNumber);
                        var owner = ownerLocator is null ? null : ResolveInstanceDbOwner(ownerLocator);
                        if (owner is null)
                        {
                            output.Text = $"[color=#d64545]Instance DB %DB{instanceDbNumber} is no longer present in the current project.[/color]";
                            return;
                        }
                        var db = owner.Value.DataBlock!;
                        var ownerDescription = owner.Value.Instance is not null
                            ? $"FB instance: {owner.Value.Instance.Name} → {owner.Value.InstanceBlock?.Name ?? owner.Value.Instance.BlockId}"
                            : $"IEC instruction: {owner.Value.InstructionBlock?.Name} · Network {owner.Value.RungIndex + 1}";
                        ShowProjectObjectProperties(db.Name,
                            "Object type: Instance data block",
                            $"Name: {db.Name}",
                            $"Number: DB{db.Number}",
                            $"Owner: {ownerDescription}",
                            "Lifecycle: Generated from its FB or IEC instruction assignment",
                            "Editable: No · change the owning assignment instead");
                        return;
                    }
                    if (id == 0) OpenInstanceDbDocument(instanceDbNumber);
                    return;
                }

                if (!metadata.StartsWith("tag-table:", StringComparison.Ordinal)
                    || metadata.Length <= "tag-table:".Length) return;
                var tableName = metadata["tag-table:".Length..];
                if (id == 1)
                {
                    var builtIn = tableName.Equals("Default tag table", StringComparison.OrdinalIgnoreCase)
                        || tableName.Equals(SceneLadderProject.SceneIoTagTableName, StringComparison.OrdinalIgnoreCase);
                    var tagCount = document.Tags.Count(tag => tag.TagTable.Equals(tableName, StringComparison.OrdinalIgnoreCase));
                    var constantCount = document.UserConstants.Count(constant => constant.TagTable.Equals(tableName, StringComparison.OrdinalIgnoreCase));
                    var deleteStatus = builtIn
                        ? "Protected · built-in project table"
                        : tagCount + constantCount == 0
                            ? "Available"
                            : $"Protected · contains {tagCount} tag(s) and {constantCount} user constant(s)";
                    ShowProjectObjectProperties(tableName,
                        "Object type: PLC tag table",
                        $"Name: {tableName}",
                        $"PLC tags: {tagCount}",
                        $"User constants: {constantCount}",
                        $"Scope: {(builtIn ? "Built-in project table" : "User-created project table")}",
                        $"Delete: {deleteStatus}",
                        $"Editable: {(builtIn ? "Contents only" : "Yes · use Rename, Duplicate, or Delete from the project tree")}");
                    return;
                }
                OpenTagDocument(tableName);
                if (id == 0) return;
                if (id == 2) renameTagTable.EmitSignal(BaseButton.SignalName.Pressed);
                else if (id == 3) duplicateTagTable.EmitSignal(BaseButton.SignalName.Pressed);
                else if (id == 4) removeTagTable.EmitSignal(BaseButton.SignalName.Pressed);
            });
            projectTreeCreationMenu.IdPressed += id => ResolvePendingEditorForms(() =>
            {
                var metadata = projectTreeContextMetadata;
                if (id == 1)
                {
                    metadata = metadata switch
                    {
                        "add-block" => "blocks",
                        "add-tag-table" => "tags",
                        "add-watch-table" => "watch",
                        _ => metadata,
                    };
                    projectTreeContextMetadata = metadata;
                    projectTreeContextLabel = metadata switch
                    {
                        "blocks" => blockFolder.GetText(0),
                        "tags" => tagItem.GetText(0),
                        "watch" => watchFolder.GetText(0),
                        _ => projectTreeContextLabel,
                    };
                    SetProjectTreeContextActionEnabled(0, true);
                    SetProjectTreeContextActionEnabled(1, true);
                    SetProjectTreeContextActionEnabled(2, false);
                    SetProjectTreeContextActionEnabled(3, false);
                    SetProjectTreeContextActionEnabled(4, false);
                    SetProjectTreeContextActionEnabled(6, false);
                    projectTreeContextMenu.EmitSignal(PopupMenu.SignalName.IdPressed, 1L);
                    return;
                }
                if (id != 5) return;
                if (metadata is "blocks" or "add-block") addBlock.EmitSignal(BaseButton.SignalName.Pressed);
                else if (metadata is "tags" or "add-tag-table") OpenTagTableCreation();
                else if (metadata is "watch" or "add-watch-table") openWatchTableCreation();
            });
        }
        watchTable.ItemActivated += () =>
        {
            // Column zero is the user's watch reference. Metadata zero is a
            // stable row ID used to preserve row identity across scans.
            var name = watchTable.GetSelected()?.GetText(0) ?? string.Empty;
            var index = document.Tags.FindIndex(tag => name == tag.Name || name.StartsWith(tag.Name + ".", StringComparison.Ordinal) || name.StartsWith(tag.Name + "[", StringComparison.Ordinal));
            if (index < 0) return;
            if (siemens) ResolvePendingEditorForms(() =>
            {
                activeTagTableName = null;
                OpenTagDocument(null, index);
                aggregateTagEditor.RevealMember(name, document.Tags[index].Name);
            });
            else
            {
                activeTagTableName = null;
                RefreshEditor();
                ShowProjectDock();
                projectTabs.CurrentTab = 1;
                SelectIndexedTreeRow(tagList, index);
                tagList.EmitSignal(Tree.SignalName.ItemSelected);
                tagList.ScrollToItem(tagList.GetSelected());
                aggregateTagEditor.RevealMember(name, document.Tags[index].Name);
            }
        };
        RefreshTagBindingOptions(SelectedTagType(), SelectedTagRole(SelectedTagType()), string.Empty);
        if (siemens)
        {
            var initialBlock = document.Blocks[0];
            var initialBlockKey = BlockDocumentKey(initialBlock.Id);
            AddEditorDocumentTab(initialBlockKey, $"{initialBlock.Name} [OB]");
            editorDocumentButtons[initialBlockKey].ButtonPressed = true;
        }
        _ladderEditorProjectReplacementResetters.Add(() =>
        {
            if (!siemens) return;
            foreach (var item in editorDocumentItems.Values.ToArray())
            {
                editorDocumentTabs.RemoveChild(item);
                item.QueueFree();
            }
            editorDocumentButtons.Clear();
            editorDocumentItems.Clear();
            editorTagDocuments.Clear();
            editorInstanceDbDocuments.Clear();
            editorWatchTableDocuments.Clear();
            activeTagTableName = null;
            selectedTagIndex = -1;

            if (document.Blocks.Count == 0)
            {
                activeEditorDocumentKey = string.Empty;
                SetEditorDocumentBody(string.Empty);
                return;
            }

            var activeBlockIndex = Math.Clamp(document.ActiveBlockIndex, 0, document.Blocks.Count - 1);
            var activeBlock = document.Blocks[activeBlockIndex];
            activeEditorDocumentKey = BlockDocumentKey(activeBlock.Id);
            var blockCode = activeBlock.BlockType switch
            {
                LadderBlockType.OrganizationBlock => "OB",
                LadderBlockType.FunctionBlock => "FB",
                LadderBlockType.DataBlock => "DB",
                _ => "FC",
            };
            AddEditorDocumentTab(activeEditorDocumentKey, $"{activeBlock.Name} [{blockCode}{activeBlockIndex + 1}]");
            editorDocumentButtons[activeEditorDocumentKey].ButtonPressed = true;
            SetEditorDocumentBody(activeEditorDocumentKey);
        });
        _ladderEditorRefreshers.Add(RefreshEditor);
        _ladderSceneDiagnosticResetters.Add(() =>
        {
            ShowValidationIssues([], openDock: false, verified: false);
            output.Text = "Scene ready. Run loads its supplied ladder; verify and load after editing.";
        });
        _ladderWatchRefreshers.Add(RefreshWatchTable);
        _ladderValidationRefreshers.Add(issues => ShowValidationIssues(issues, openDock: true));
        refreshEditorAfterInitialization = RefreshEditor;
        RefreshEditor();
        static void AddVisibleSplitGrip(SplitContainer split, string text)
        {
            foreach (var dragArea in split.GetDragAreaControls())
            {
                var grip = new Label
                {
                    Name = "VisibleResizeGrip",
                    Text = text,
                    MouseFilter = Control.MouseFilterEnum.Ignore,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center,
                };
                grip.AddThemeColorOverride("font_color", new Color("ffffff"));
                grip.AddThemeColorOverride("font_shadow_color", new Color("17242c"));
                grip.AddThemeConstantOverride("shadow_offset_x", 1);
                grip.AddThemeConstantOverride("shadow_offset_y", 1);
                grip.AddThemeFontSizeOverride("font_size", 12);
                grip.SetAnchorsPreset(Control.LayoutPreset.Center);
                grip.OffsetLeft = -14;
                grip.OffsetTop = -10;
                grip.OffsetRight = 14;
                grip.OffsetBottom = 10;
                dragArea.AddChild(grip);
            }
        }
        AddVisibleSplitGrip(work, "|||");
        AddVisibleSplitGrip(editorAndTasks, "|||");
        AddVisibleSplitGrip(editorAndInspector, "— —");
        return root;
    }

    private void BuildApplicationSettingsDialog()
    {
        var settings = LoadApplicationSettings();
        _mcpUiEnabled = new CheckButton
        {
            Text = "Enable RungProof MCP UI integration",
            ButtonPressed = settings.McpUiEnabled,
            TooltipText = "Controls RungProof's local MCP menu affordances; it does not unregister the external Codex MCP server.",
        };
        _showSafetyNotices = new CheckButton
        {
            Text = "Show offline safety boundary notices",
            ButtonPressed = settings.ShowSafetyNotices,
        };
        var body = new VBoxContainer { CustomMinimumSize = new Vector2(560, 0) };
        body.AddChild(new Label
        {
            Text = "These settings are local to this simulator UI. The MCP server remains simulation-only and never creates a physical PLC connection.",
            AutowrapMode = TextServer.AutowrapMode.WordSmart,
        });
        body.AddChild(_mcpUiEnabled);
        body.AddChild(_showSafetyNotices);
        var scaleRow = new HBoxContainer { Name = "InterfaceScaleSettingRow" };
        scaleRow.AddChild(new Label
        {
            Text = "Interface scale",
            CustomMinimumSize = new Vector2(180, 0),
            VerticalAlignment = VerticalAlignment.Center,
        });
        _interfaceScaleSelector = new OptionButton
        {
            Name = "InterfaceScaleSetting",
            CustomMinimumSize = new Vector2(210, 34),
            TooltipText = "Scale the complete workbench. Ladder diagram zoom remains independent.",
        };
        for (var index = 0; index < DesktopUiScalePolicy.Settings.Length; index++)
        {
            var setting = DesktopUiScalePolicy.Settings[index];
            var percent = DesktopUiScalePolicy.ResolvePercent(setting, GetWindow().Size.X, GetWindow().Size.Y);
            _interfaceScaleSelector.AddItem(
                setting == "auto" ? $"Auto ({percent}% for this window)" : $"{percent}%",
                index);
        }
        _interfaceScaleSelector.Select(Array.IndexOf(
            DesktopUiScalePolicy.Settings, DesktopUiScalePolicy.NormalizeSetting(settings.InterfaceScale)));
        scaleRow.AddChild(_interfaceScaleSelector);
        body.AddChild(scaleRow);
        body.AddChild(new Label
        {
            Text = "Auto uses 75% for small windows, 85% for 1600×900-class windows, and 100% when more workspace is available.",
            AutowrapMode = TextServer.AutowrapMode.WordSmart,
        });
        body.AddChild(new Label
        {
            Text = "Codex manages server registration. Use Codex MCP settings to unregister the server; this menu controls only RungProof UI behavior.",
            AutowrapMode = TextServer.AutowrapMode.WordSmart,
        });
        _applicationSettingsDialog = new AcceptDialog
        {
            Name = "ApplicationSettingsDialog",
            Title = "MCP & Application Settings",
            DialogText = string.Empty,
            Exclusive = true,
        };
        _applicationSettingsDialog.AddChild(body);
        _applicationSettingsDialog.Confirmed += SaveApplicationSettings;
        AddChild(_applicationSettingsDialog);
        SetMcpUiEnabled(_mcpUiEnabled.ButtonPressed, persist: false);
        AddReducedMotionSetting(body, settings.ReducedMotion);
    }

    public bool IsExternalMode => _externalMode;

    private void BuildExternalPlcDialog()
    {
        _externalProfileSelector = new OptionButton
        {
            Name = "ExternalProfileSelector",
            CustomMinimumSize = new Vector2(420, 34),
        };
        _externalProfileSelector.AddItem("scene-1-db14-interface.json");
        _externalProfileSelector.AddItem("scene-2-db14-pusher-interface.json");
        _externalProfileSelector.ItemSelected += _ =>
        {
            InvalidateExternalApproval();
            RefreshExternalProfileDetails();
        };
        _externalProfileDetails = new RichTextLabel
        {
            Name = "ExternalProfileDetails",
            BbcodeEnabled = true,
            FitContent = false,
            SizeFlagsVertical = Control.SizeFlags.Fill,
            CustomMinimumSize = new Vector2(700, 260),
        };
        _externalAuthorization = new CheckButton
        {
            Name = "ExternalAuthorization",
            Text = "I verified the active CPU, rack/slot, profile, and exact write scope.",
        };

        var body = new VBoxContainer { Name = "ExternalPlcBody", CustomMinimumSize = new Vector2(760, 0) };
        body.AddChild(new Label
        {
            Text = "The External PLC mode uses the existing guarded S7 runtime and the selected validated profile. It does not modify the PLC project or safety logic.",
            AutowrapMode = TextServer.AutowrapMode.WordSmart,
            // Godot 4.7 autowrap needs a bounded width before the first layout.
            // Otherwise this initially zero-width label inflates the dialog.
            CustomMaximumSize = new Vector2(1040, -1),
        });
        body.AddChild(ConnectionSettingRow("Profile", _externalProfileSelector));
        body.AddChild(_externalProfileDetails);
        body.AddChild(_externalAuthorization);
        var actions = new HBoxContainer();
        var verify = ToolbarButton("VerifyExternalProfile", "VERIFY PROFILE", new Color("3c5968"));
        var diagnostic = ToolbarButton("RunExternalDiagnostic", "READ-ONLY PLC TEST", new Color("3c5968"));
        var connect = ToolbarButton("ConnectExternalPlc", "CONNECT EXTERNAL PLC", new Color("276b89"));
        var disconnect = ToolbarButton("DisconnectExternalPlc", "DISCONNECT", new Color("6d3d42"));
        actions.AddChild(verify);
        actions.AddChild(diagnostic);
        actions.AddChild(connect);
        actions.AddChild(disconnect);
        body.AddChild(actions);
        _externalPlcDialog = new AcceptDialog
        {
            Name = "ExternalPlcDialog",
            Title = "External PLC Settings / Tests",
            DialogText = string.Empty,
            Exclusive = true,
            MinSize = new Vector2I(820, 620),
        };
        _externalPlcDialog.OkButtonText = "CLOSE";
        _externalPlcDialog.AddChild(body);
        verify.Pressed += RefreshExternalProfileDetails;
        diagnostic.Pressed += RunExternalDiagnostic;
        connect.Pressed += ConnectExternalPlc;
        disconnect.Pressed += DisconnectExternalPlc;
        AddChild(_externalPlcDialog);
        RefreshExternalProfileDetails();
    }

    private static Control ConnectionSettingRow(string label, Control editor)
    {
        var row = new HBoxContainer { CustomMinimumSize = new Vector2(0, 38) };
        row.AddChild(new Label { Text = label, CustomMinimumSize = new Vector2(120, 0), VerticalAlignment = VerticalAlignment.Center });
        row.AddChild(editor);
        return row;
    }

    public void ShowExternalPlcDialog()
    {
        if (RejectChallengeExternalOperation()) return;
        if (RuntimeBuildPolicy.IsOfflineDemo)
        {
            SetWorkspaceStatus("Offline demo · external PLC transport is disabled");
            return;
        }
        SetExternalMode(true);
        RefreshExternalProfileDetails();
        var viewport = GetViewport().GetVisibleRect().Size;
        _externalPlcDialog.PopupCentered(new Vector2I(
            (int)Math.Min(viewport.X - 48, 1040), (int)Math.Min(viewport.Y - 80, 620)));
    }

    private void SetExternalMode(bool enabled)
    {
        // Choosing the already-active local source must not retire a challenge or disconnect it.
        if (IsChallengeDraftActive && !enabled && !_externalMode) return;
        if (RejectChallengeExternalOperation()) return;
        if (enabled && RuntimeBuildPolicy.IsOfflineDemo)
        {
            SetWorkspaceStatus("Offline demo · built-in simulator remains selected");
            return;
        }
        if (!enabled && _connection is ExternalPlcRuntimeClient external
            && external.State != ConnectionState.Disconnected)
        {
            external.Disconnect();
        }
        var modeChanged = _externalMode != enabled;
        if (modeChanged) InvalidateExternalApproval();
        _externalMode = enabled;
        if (modeChanged) ControllerModeChanged?.Invoke(enabled);
        if (modeChanged) RecordOperatorEvent(enabled ? "External PLC source selected" : "Built-in simulator source selected");
        var popup = GetNodeOrNull<MenuButton>("Workspace/Toolbar/ToolbarMargin/ToolbarRow/PlcMenu")?.GetPopup();
        if (popup is not null)
        {
            popup.SetItemChecked(popup.GetItemIndex(10), !enabled);
            popup.SetItemChecked(popup.GetItemIndex(11), enabled);
        }
        _workspaceStatus.Text = enabled
            ? "EXTERNAL PLC MODE · select a matching profile and connect before RUN"
            : "BUILT-IN SIMULATOR MODE · local virtual controller owns the scene";
        _workspaceStatus.AddThemeColorOverride("font_color", enabled ? new Color("f1aa5b") : new Color("65d49a"));
        RefreshConnection();
    }

    private void RefreshExternalProfileDetails()
    {
        if (RejectChallengeExternalOperation()) return;
        if (_externalProfileDetails is null) return;
        var profile = _externalProfileSelector.GetItemText(_externalProfileSelector.Selected);
        if (_activeScene is null)
        {
            _externalProfileDetails.Text = "[color=#f1aa5b]No scene is loaded.[/color]";
            return;
        }
        if (!string.Equals(_activeScene.PlcTestProfile, profile, StringComparison.OrdinalIgnoreCase))
        {
            _externalProfileDetails.Text = $"[color=#f1aa5b]PROFILE MISMATCH[/color]\nActive scene: {Escape(_activeScene.Id)}\nRequired profile: {Escape(_activeScene.PlcTestProfile ?? "none")}\nSelected: {Escape(profile)}\n\nSelect the profile declared by the scene before connecting.";
            return;
        }
        if (_connection is not ExternalPlcRuntimeClient external)
        {
            _externalProfileDetails.Text = "[color=#ef7777]External runtime bridge is unavailable in this build.[/color]";
            return;
        }
        if (external.IsBusy)
        {
            _externalProfileDetails.Text = "Bridge request in progress…";
            return;
        }
        var generation = _externalSelectionGeneration;
        var scene = _activeScene;
        _externalProfileDetails.Text = "Validating the local profile…";
        external.DescribeProfile(profile, descriptor =>
        {
            if (!CanCompleteExternalRequest(generation)) return;
            ExternalSceneContract.Validate(scene.Simulation, descriptor);
            if (_verifiedExternalDescriptor is JsonElement previous && previous.GetRawText() != descriptor.GetRawText())
                _externalAuthorization.ButtonPressed = false;
            _verifiedExternalDescriptor = descriptor;
            _externalProfileDetails.Text = ExternalProfilePresentation.Format(descriptor);
        }, exception =>
        {
            if (!CanCompleteExternalRequest(generation)) return;
            _verifiedExternalDescriptor = null;
            _externalAuthorization.ButtonPressed = false;
            _externalProfileDetails.Text = $"[color=#ef7777]PROFILE TEST FAILED[/color]\n{Escape(exception.Message)}";
        });
    }

    public bool VerifyExternalDialogBounds(out string result)
    {
        var body = _externalPlcDialog.GetNode<VBoxContainer>("ExternalPlcBody");
        var viewport = GetViewport().GetVisibleRect().Size;
        var size = _externalPlcDialog.Size;
        var actions = (Control)body.GetChild(body.GetChildCount() - 1);
        var controlsFit = _externalAuthorization.GetGlobalRect().End.Y <= size.Y
            && actions.GetGlobalRect().End.Y <= size.Y && _externalPlcDialog.GetOkButton().GetGlobalRect().End.Y <= size.Y;
        var profileValid = _verifiedExternalDescriptor is not null && _externalProfileDetails.Text.Contains("PROFILE VALID", StringComparison.Ordinal);
        var profileFailure = profileValid ? string.Empty : _externalProfileDetails.Text.Replace('\n', ' ');
        result = $"window={size} viewport={viewport} controlsFit={controlsFit} profileValid={profileValid} connection={_connection.State} profileDetail={profileFailure}";
        return size.X <= viewport.X && size.Y <= viewport.Y && controlsFit && profileValid && _connection.State == ConnectionState.Disconnected;
    }

    private void RunExternalDiagnostic()
    {
        if (RejectChallengeExternalOperation()) return;
        if (_connection is not ExternalPlcRuntimeClient external)
        {
            _externalProfileDetails.Text = "[color=#ef7777]External runtime bridge is unavailable in this build.[/color]";
            return;
        }
        var profile = _externalProfileSelector.GetItemText(_externalProfileSelector.Selected);
        if (external.State != ConnectionState.Disconnected)
        {
            _externalProfileDetails.Text = "Disconnect the active session before running a separate read-only PLC test.";
            return;
        }
        if (!CanUseExternalProfile(profile) || external.IsBusy) return;
        var generation = _externalSelectionGeneration;
        _externalProfileDetails.Text = "Read-only PLC test in progress…";
        external.RunReadOnlyDiagnostic(profile, result =>
        {
            if (!CanCompleteExternalRequest(generation)) return;
            var lines = result.GetProperty("items").EnumerateArray().Select(item =>
            {
                var status = item.GetProperty("status").GetString()?.ToUpperInvariant() ?? "INFO";
                var label = item.GetProperty("label").GetString() ?? string.Empty;
                var detail = item.GetProperty("detail").GetString() ?? string.Empty;
                return $"[{status}] {Escape(label)} · {Escape(detail)}";
            });
            _externalProfileDetails.Text =
                $"[b]READ-ONLY PLC TEST[/b]\n{Escape(result.GetProperty("summary").GetString() ?? "No result.")}\n\n" +
                string.Join("\n", lines);
        }, exception =>
        {
            if (!CanCompleteExternalRequest(generation)) return;
            _externalProfileDetails.Text = $"[color=#ef7777]READ-ONLY PLC TEST FAILED[/color]\n{Escape(exception.Message)}";
        });
    }

    private void ConnectExternalPlc()
    {
        if (RejectChallengeExternalOperation()) return;
        if (_activeScene is null || _connection is not ExternalPlcRuntimeClient external)
        {
            SetWorkspaceStatus("External PLC connection unavailable · no matching scene/runtime", isError: true);
            return;
        }
        var profile = _externalProfileSelector.GetItemText(_externalProfileSelector.Selected);
        if (!CanUseExternalProfile(profile) || external.IsBusy) return;
        if (!_externalAuthorization.ButtonPressed)
        {
            _externalProfileDetails.Text = "[color=#f1aa5b]Connection requires exact-scope authorization.[/color]\n\n" + _externalProfileDetails.Text;
            return;
        }
        if (_verifiedExternalDescriptor is not JsonElement verified)
        {
            _externalProfileDetails.Text = "Verify the matching local profile before authorizing a connection.";
            return;
        }
        var generation = _externalSelectionGeneration;
        // Re-read the local profile before connecting. A file edit invalidates
        // approval just as a scene/profile selection change does.
        external.DescribeProfile(profile, descriptor =>
        {
            if (!CanCompleteExternalRequest(generation) || !_externalAuthorization.ButtonPressed) return;
            ExternalSceneContract.Validate(_activeScene!.Simulation, descriptor);
            if (verified.GetRawText() != descriptor.GetRawText())
            {
                InvalidateExternalApproval();
                _externalProfileDetails.Text = "Profile changed after verification. Verify and authorize its new scope.";
                return;
            }
            var scope = descriptor.GetProperty("writeScope").EnumerateArray()
                .Select(item => item.Clone())
                .ToArray();
            if (RejectChallengeExternalOperation()) return;
            SetExternalMode(true);
            var connectionGeneration = _externalSelectionGeneration;
            external.Connect(profile, _activeScene.Id, scope, _ =>
            {
                if (!CanCompleteExternalRequest(connectionGeneration)) return;
                SetWorkspaceStatus("EXTERNAL PLC CONNECTED · waiting for guarded readiness");
                _externalPlcDialog.Hide();
            }, exception => { if (CanCompleteExternalRequest(connectionGeneration)) ReportExternalConnectionFailure(exception); }, descriptor.GetProperty("connectTimeoutMs").GetInt32(), descriptor);
        }, exception => { if (CanCompleteExternalRequest(generation)) ReportExternalConnectionFailure(exception); });
    }

    private bool RejectChallengeExternalOperation()
    {
        if (!IsChallengeDraftActive) return false;
        // Invalidate descriptors even if a dialog/request began before challenge entry.
        // No transport operation is invoked by this rejection path.
        _externalSelectionGeneration++;
        _verifiedExternalDescriptor = null;
        if (_externalAuthorization is not null) _externalAuthorization.ButtonPressed = false;
        _externalPlcDialog?.Hide();
        const string guidance = "Leave the offline challenge before selecting external PLC mode, settings, diagnostics or connection.";
        if (_externalProfileDetails is not null) _externalProfileDetails.Text = guidance;
        SetWorkspaceStatus(guidance);
        return true;
    }

    private bool CanCompleteExternalRequest(int generation)
        => !RejectChallengeExternalOperation() && generation == _externalSelectionGeneration;

    /// <summary>Opt-in native source-boundary probe: every path rejects before a bridge call.</summary>
    public bool VerifyChallengeExternalGuards(out string diagnostic)
    {
        if (!IsChallengeDraftActive || _externalMode || _connection.State != ConnectionState.Disconnected)
        { diagnostic = "requires active local challenge with disconnected transport"; return false; }
        var modeEvents = 0;
        void CountMode(bool _) => modeEvents++;
        ControllerModeChanged += CountMode;
        try
        {
            var generation = _externalSelectionGeneration;
            SetExternalMode(false);
            var sameLocalNoOp = _externalSelectionGeneration == generation && modeEvents == 0;
            _verifiedExternalDescriptor = JsonSerializer.SerializeToElement(new { verified = true });
            _externalAuthorization.ButtonPressed = true;
            SetExternalMode(true);
            ShowExternalPlcDialog();
            RefreshExternalProfileDetails();
            RunExternalDiagnostic();
            ConnectExternalPlc();
            var callbackRejected = !CanCompleteExternalRequest(generation);
            var blocked = !_externalMode && modeEvents == 0 && !_externalPlcDialog.Visible
                && _verifiedExternalDescriptor is null && !_externalAuthorization.ButtonPressed
                && _connection.State == ConnectionState.Disconnected
                && (_connection is not ExternalPlcRuntimeClient external || !external.IsBusy);
            diagnostic = $"sameLocalNoOp={sameLocalNoOp} externalPathsBlocked={blocked} staleCallbackRejected={callbackRejected} modeEvents={modeEvents}; no bridge operation requested";
            return sameLocalNoOp && blocked && callbackRejected;
        }
        finally { ControllerModeChanged -= CountMode; }
    }

    private void ReportExternalConnectionFailure(Exception exception)
    {
        SetWorkspaceStatus($"External PLC connection failed · {exception.Message}", isError: true);
        RefreshConnection();
    }

    private bool CanUseExternalProfile(string profile)
    {
        if (RejectChallengeExternalOperation()) return false;
        if (_activeScene is null || !string.Equals(_activeScene.PlcTestProfile, profile, StringComparison.OrdinalIgnoreCase))
        {
            _externalProfileDetails.Text = "[color=#ef7777]PROFILE MISMATCH · select the profile declared by the active scene.[/color]";
            _externalAuthorization.ButtonPressed = false;
            return false;
        }
        return true;
    }

    private void InvalidateExternalApproval()
    {
        _externalSelectionGeneration++;
        _verifiedExternalDescriptor = null;
        if (_externalAuthorization is not null) _externalAuthorization.ButtonPressed = false;
        if (_connection is ExternalPlcRuntimeClient external && (external.IsBusy || external.State != ConnectionState.Disconnected))
            external.Disconnect();
    }

    private void DisconnectExternalPlc()
    {
        if (_connection is ExternalPlcRuntimeClient external) external.Disconnect();
        SetWorkspaceStatus("External PLC disconnected");
        RefreshConnection();
    }

    public bool VerifyExternalProfileGuards(out string result)
    {
        if (RuntimeBuildPolicy.IsOfflineDemo)
        {
            var popup = GetNode<MenuButton>("Workspace/Toolbar/ToolbarMargin/ToolbarRow/PlcMenu").GetPopup();
            // Deliberately emit the disabled actions too: presentation alone
            // must not be the policy boundary or stop local simulation.
            popup.EmitSignal(PopupMenu.SignalName.IdPressed, 11);
            popup.EmitSignal(PopupMenu.SignalName.IdPressed, 12);
            ConnectExternalPlc();
            RunExternalDiagnostic();
            var blocked = _connection is DisconnectedRuntimeClient && !_externalMode
                && !_externalPlcDialog.Visible && _connection.State == ConnectionState.Disconnected
                && popup.IsItemDisabled(popup.GetItemIndex(11)) && popup.IsItemDisabled(popup.GetItemIndex(12));
            result = $"offlineBuildBlocked={blocked} sourceRemainsLocal={!_externalMode}";
            return blocked;
        }
        if (_activeScene is null || _connection is not ExternalPlcRuntimeClient external || external.IsBusy)
        {
            result = "guard verification requires an idle offline scene";
            return false;
        }
        var selected = _externalProfileSelector.Selected;
        var details = _externalProfileDetails.Text;
        var wrong = _activeScene.PlcTestProfile == _externalProfileSelector.GetItemText(0) ? 1 : 0;
        _externalProfileSelector.Select(wrong);
        _externalAuthorization.ButtonPressed = true;
        ConnectExternalPlc();
        var mismatchBlocked = !external.IsBusy && external.State == ConnectionState.Disconnected
            && !_externalAuthorization.ButtonPressed && _externalProfileDetails.Text.Contains("PROFILE MISMATCH", StringComparison.Ordinal);
        _externalAuthorization.ButtonPressed = true;
        _verifiedExternalDescriptor = JsonSerializer.SerializeToElement(new { verified = true });
        _externalProfileSelector.EmitSignal(OptionButton.SignalName.ItemSelected, wrong);
        var selectionClearsApproval = !_externalAuthorization.ButtonPressed && _verifiedExternalDescriptor is null && !external.IsBusy;
        RunExternalDiagnostic();
        var diagnosticMismatchBlocked = !external.IsBusy;
        _externalProfileSelector.Select(selected);
        _externalProfileDetails.Text = details;
        result = $"mismatchBlocked={mismatchBlocked} selectionClearsApproval={selectionClearsApproval} diagnosticMismatchBlocked={diagnosticMismatchBlocked} noTransport=True";
        return mismatchBlocked && selectionClearsApproval && diagnosticMismatchBlocked;
    }

    private void SetMcpUiEnabled(bool enabled, bool persist = true)
    {
        _mcpUiEnabled.ButtonPressed = enabled;
        var index = _toolsPopup.GetItemIndex(McpToggleMenuId);
        if (index >= 0) _toolsPopup.SetItemText(index, $"MCP Integration: {(enabled ? "Enabled" : "Disabled")}");
        if (persist) SaveApplicationSettings();
    }

    private void ApplyInterfaceScale(string setting, bool persist = true)
    {
        if (_applyingInterfaceScale) return;
        _applyingInterfaceScale = true;
        try
        {
            _interfaceScaleSetting = DesktopUiScalePolicy.NormalizeSetting(setting);
            var window = GetWindow();
            _resolvedInterfaceScalePercent = DesktopUiScalePolicy.ResolvePercent(
                _interfaceScaleSetting, window.Size.X, window.Size.Y);
            window.ContentScaleMode = Window.ContentScaleModeEnum.CanvasItems;
            window.ContentScaleSize = Vector2I.Zero;
            window.ContentScaleFactor = _resolvedInterfaceScalePercent / 100.0f;
            RefreshInterfaceScaleControls();
        }
        finally
        {
            _applyingInterfaceScale = false;
        }
        if (persist) SaveApplicationSettings();
    }

    private void RefreshInterfaceScaleControls()
    {
        if (_viewPopup is not null && GodotObject.IsInstanceValid(_viewPopup))
        {
            for (var index = 0; index < DesktopUiScalePolicy.Settings.Length; index++)
            {
                var itemId = InterfaceScaleMenuBaseId + index;
                var itemIndex = _viewPopup.GetItemIndex(itemId);
                if (itemIndex < 0) continue;
                var setting = DesktopUiScalePolicy.Settings[index];
                _viewPopup.SetItemChecked(itemIndex, setting == _interfaceScaleSetting);
                if (setting == "auto")
                    _viewPopup.SetItemText(itemIndex, DesktopUiScalePolicy.Label(setting, _resolvedInterfaceScalePercent));
            }
        }
        if (_interfaceScaleSelector is not null && GodotObject.IsInstanceValid(_interfaceScaleSelector))
        {
            var selected = Array.IndexOf(DesktopUiScalePolicy.Settings, _interfaceScaleSetting);
            if (selected >= 0) _interfaceScaleSelector.Select(selected);
            var autoIndex = _interfaceScaleSelector.GetItemIndex(0);
            if (autoIndex >= 0)
                _interfaceScaleSelector.SetItemText(autoIndex, $"Auto ({_resolvedInterfaceScalePercent}% for this window)");
        }
    }

    private void SaveApplicationSettings()
    {
        if (_interfaceScaleSelector is not null && GodotObject.IsInstanceValid(_interfaceScaleSelector)
            && _interfaceScaleSelector.Selected >= 0)
            _interfaceScaleSetting = DesktopUiScalePolicy.Settings[_interfaceScaleSelector.Selected];
        ApplyInterfaceScale(_interfaceScaleSetting, persist: false);
        var payload = new Godot.Collections.Dictionary
        {
            ["schemaVersion"] = 2,
            ["mcpUiEnabled"] = _mcpUiEnabled.ButtonPressed,
            ["showSafetyNotices"] = _showSafetyNotices.ButtonPressed,
            ["reducedMotion"] = ReducedMotion,
            ["interfaceScale"] = _interfaceScaleSetting,
        };
        using var file = FileAccess.Open(SettingsPath, FileAccess.ModeFlags.Write);
        file?.StoreString(Json.Stringify(payload, "  "));
        SetMcpUiEnabled(_mcpUiEnabled.ButtonPressed, persist: false);
    }

    private static (bool McpUiEnabled, bool ShowSafetyNotices, bool ReducedMotion, string InterfaceScale) LoadApplicationSettings()
    {
        if (!FileAccess.FileExists(SettingsPath)) return (true, true, true, "auto");
        try
        {
            using var file = FileAccess.Open(SettingsPath, FileAccess.ModeFlags.Read);
            var parsed = Json.ParseString(file?.GetAsText() ?? string.Empty).AsGodotDictionary();
            return (
                parsed.ContainsKey("mcpUiEnabled") ? parsed["mcpUiEnabled"].AsBool() : true,
                parsed.ContainsKey("showSafetyNotices") ? parsed["showSafetyNotices"].AsBool() : true,
                parsed.ContainsKey("reducedMotion") ? parsed["reducedMotion"].AsBool() : true,
                DesktopUiScalePolicy.NormalizeSetting(
                    parsed.ContainsKey("interfaceScale") ? parsed["interfaceScale"].AsString() : "auto"));
        }
        catch
        {
            return (true, true, true, "auto");
        }
    }

    public bool IsLadderView => _productView is "ladder" or "split";

    public bool VerifyInterfaceScaleControls(out string result)
    {
        var menuItems = 0;
        var checkedItems = 0;
        var selectedSetting = string.Empty;
        if (_viewPopup is not null && GodotObject.IsInstanceValid(_viewPopup))
        {
            for (var index = 0; index < DesktopUiScalePolicy.Settings.Length; index++)
            {
                var itemIndex = _viewPopup.GetItemIndex(InterfaceScaleMenuBaseId + index);
                if (itemIndex < 0) continue;
                menuItems++;
                if (_viewPopup.IsItemChecked(itemIndex))
                {
                    checkedItems++;
                    selectedSetting = DesktopUiScalePolicy.Settings[index];
                }
            }
        }
        var selectorItems = _interfaceScaleSelector is not null
            && GodotObject.IsInstanceValid(_interfaceScaleSelector)
            ? _interfaceScaleSelector.ItemCount
            : 0;
        var expectedFactor = _resolvedInterfaceScalePercent / 100.0f;
        var factorMatches = Math.Abs(GetWindow().ContentScaleFactor - expectedFactor) < 0.001f;
        var passed = menuItems == DesktopUiScalePolicy.Settings.Length
            && selectorItems == DesktopUiScalePolicy.Settings.Length
            && checkedItems == 1
            && selectedSetting == _interfaceScaleSetting
            && factorMatches;
        result = $"setting={_interfaceScaleSetting} resolved={_resolvedInterfaceScalePercent}% "
            + $"menuItems={menuItems} selectorItems={selectorItems} checked={checkedItems} factorMatches={factorMatches}";
        return passed;
    }

    public bool VerifyWorkspaceLoadMenuBinding(out string result)
    {
        var popup = GetNodeOrNull<MenuButton>(
            "Workspace/Toolbar/ToolbarMargin/ToolbarRow/FileMenu")?.GetPopup();
        var feedback = GetNodeOrNull<AcceptDialog>("WorkspaceFeedbackDialog");
        if (popup is null || feedback is null)
        {
            result = "File menu or workspace feedback dialog is unavailable";
            return false;
        }
        feedback.Hide();
        // Verifies that the visible File-menu item is connected to the
        // operator load action. Native mouse/keyboard verification requires
        // an interactive window; headless Godot has no real input surface.
        popup.EmitSignal(PopupMenu.SignalName.IdPressed, 1L);
        var invoked = feedback.Visible;
        feedback.Hide();
        result = invoked
            ? "File -> Load Last Workspace invoked and displayed feedback"
            : "File -> Load Last Workspace produced no visible feedback";
        return invoked;
    }

    public bool VerifyExternalPlcMenu(out string result)
    {
        var popup = GetNodeOrNull<MenuButton>(
            "Workspace/Toolbar/ToolbarMargin/ToolbarRow/PlcMenu")?.GetPopup();
        if (popup is null)
        {
            result = "PLC menu is unavailable";
            return false;
        }
        var labels = Enumerable.Range(0, popup.ItemCount)
            .Select(popup.GetItemText)
            .ToHashSet(StringComparer.Ordinal);
        var passed = labels.Contains("Built-in Simulator")
            && labels.Contains("External PLC")
            && labels.Contains("External PLC Settings / Tests…");
        result = passed
            ? "PLC menu exposes Built-in Simulator, External PLC, and External PLC Settings / Tests"
            : "PLC menu is missing one or more runtime mode entries";
        return passed;
    }

    public bool VerifyScenarioMenuSelection(out string result)
    {
        var popup = GetNodeOrNull<MenuButton>(
            "Workspace/Toolbar/ToolbarMargin/ToolbarRow/SceneMenu")?.GetPopup();
        if (popup is null)
        {
            result = "Scenario menu is unavailable";
            return false;
        }
        // Exercise each real menu binding; checking the authored files alone
        // cannot detect a later menu item loading another scene's editor draft.
        var verified = 0;
        // Leave Demo 1 active, as before, for the subsequent cross-scene open check.
        foreach (var expected in AuthoredDemos.Skip(1).Concat(AuthoredDemos.Take(1)))
        {
            var index = Enumerable.Range(0, popup.ItemCount)
                .FirstOrDefault(item => popup.GetItemText(item) == expected.Label, -1);
            if (index < 0)
            {
                result = $"Scenario menu item is missing: {expected.Label}";
                return false;
            }
            popup.EmitSignal(PopupMenu.SignalName.IdPressed, popup.GetItemId(index));
            if (_activeScene?.Id != expected.SceneId
                || _ladderDocument.SourceSceneId != expected.SceneId
                || _sceneTitle.Text != expected.Label)
            {
                result = $"Scenario menu mismatch: {expected.Label}; scene={_activeScene?.Id ?? "<none>"} editor={_ladderDocument.SourceSceneId} title={_sceneTitle.Text}";
                return false;
            }
            var program = _ladderDocument.BuildProgram();
            var compile = LadderCompiler.Compile(program);
            var bindingIssues = SceneIoBindingValidator.Validate(program, ScenePoints());
            var hasAuthored = AuthoredDemoLadderPrograms.TryCreate(expected.SceneId, out var authored);
            if (hasAuthored)
                SceneLadderProject.EnsureSceneIoTable(authored, ScenePoints(),
                    _runtime?.Points ?? new Dictionary<string, object?>(), out _);
            if (!compile.IsValid || bindingIssues.Count > 0
                || !hasAuthored
                || LadderEditorProjectJson.Save(_ladderDocument) != LadderEditorProjectJson.Save(authored))
            {
                result = $"Scenario menu loaded an invalid or different demo draft: {expected.Label}; compile={compile.IsValid} bindingIssues={bindingIssues.Count}";
                return false;
            }
            verified++;
        }
        result = $"demoSelections={verified}/{AuthoredDemos.Length} scene/editor/title/program/interface match";
        return verified == AuthoredDemos.Length;
    }

